desc={
'Linear Regression':('Linear','Fits a weighted sum of vehicle characteristics. Useful as a simple, interpretable starting point.'),
'Ridge':('Linear','Shrinks linear coefficients to reduce instability from correlated inputs.'),
'Lasso':('Linear','Penalizes coefficient size and can shrink some coefficients to zero.'),
'Elastic Net':('Linear','Combines the coefficient penalties of Ridge and Lasso.'),
'Bayesian Ridge':('Linear','Fits a regularized linear relationship with Bayesian estimation of its precision parameters.'),
'Huber Regression':('Robust linear','Uses a robust loss to reduce the influence of very large residuals.'),
'SGD Regression':('Linear','Learns a regularized linear model through incremental gradient updates.'),
'K-Nearest Neighbors':('Neighbors','Predicts from nearby records in the encoded and scaled feature space.'),
'Decision Tree':('Tree','Splits feature space into price groups using a depth-limited tree.'),
'Extra Tree':('Tree','Uses randomized split thresholds in one tree. This differs from the multi-tree Extra Trees ensemble.'),
'Random Forest':('Ensemble','Averages many bootstrapped decision trees to reduce variability.'),
'Extra Trees':('Ensemble','Averages trees with randomized split thresholds to capture nonlinear relationships.'),
'Gradient Boosting':('Boosting','Adds trees sequentially to correct earlier prediction errors.'),
'Histogram Gradient Boosting':('Boosting','Bins features before growing boosted trees, reducing computational cost.'),
'AdaBoost':('Boosting','Combines weak regressors while increasing emphasis on harder training records.'),
'Support Vector Regression':('Kernel','Uses an RBF kernel to fit nonlinear relationships with an error-tolerance margin.')}
